import { PuzzleWithCutscene } from "@hunt/puzzle-components";
import React from "react";
import { hydrateRoot } from "react-dom/client";

const elem = document.getElementById("puzzle-content-root");
if (elem) {
  hydrateRoot(elem, <PuzzleWithCutscene id="kc03" />);
} else {
  console.error(
    "Could not mount PuzzleWithCutscene because #puzzle-content-root was nowhere to be found",
  );
}
